// Dynamic lot sizing & equity circuit breaker
double CalculateNormalizedLot(string sym, double risk_pct, double sl_pts) {
   double equity   = AccountInfoDouble(ACCOUNT_EQUITY);
   double tick_val = SymbolInfoDouble(sym, SYMBOL_TRADE_TICK_VALUE);
   double vol_step = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
   double raw_lot  = (equity * (risk_pct / 100.0)) / (sl_pts * tick_val);
   return MathFloor(raw_lot / vol_step) * vol_step;
}

// Fair Value Gap displacement check
bool VerifyDisplacement(const MqlRates &r[]) {
   double fvg_gap = r[0].low - r[2].high;
   return (fvg_gap >= InpMinDisplacementPts * _Point);
}
